// Every number in the briefing comes from the Gold layer (briefing.sql); the LLM only writes the text.
const result = $input.first().json;
if (result.status?.state !== 'SUCCEEDED') {
  throw new Error(`Briefing query ${result.status?.state}: ${result.status?.error?.message ?? 'no result'}`);
}
const data = JSON.parse(result.result.data_array[0][0]);
const { language } = $('Config').first().json;

const prompt = `You are a public safety analyst writing a short weekly executive briefing for managers.
Write in ${language}.
Rules:
- Use ONLY the numbers in the JSON below. Do not compute new statistics and do not guess causes.
- CVLI = intentional lethal violent crimes (homicide, feminicide, robbery followed by death, bodily injury followed by death).
- Rates are per 100,000 inhabitants and annualized; the analysis window goes from the month of window_start to the month of window_end.
- lisa_cluster "High-High" means a high-rate municipality surrounded by high-rate neighbors (a regional cluster).
- SINESP data come from police records sent by each state, so differences between states can also reflect reporting.
- Vehicle crimes and drug seizures are published by state only (never per municipality), so do not suggest municipal
  analyses of them.
Structure:
1. <h3> Summary </h3> one paragraph with the national picture;
2. <h3> Highlights </h3> 3 to 5 bullets on states and large cities that stand out and on spatial clusters;
3. <h3> Data freshness and quality </h3> what changed in the last 7 days and names awaiting review;
4. <h3> Suggested question </h3> one question worth asking the AI assistant next.
Output an HTML fragment using only <h3>, <p>, <ul>, <li> and <strong>. No markdown, no code fences.

DATA:
${JSON.stringify(data, null, 2)}`;

return [{ json: { data, prompt } }];

// The tables are built from the data, not by the LLM.
const response = $input.first().json;
const text = (response.candidates?.[0]?.content?.parts ?? []).map(p => p.text ?? '').join('')
  .replace(/^\s*```(?:html)?\s*/i, '').replace(/\s*```\s*$/, '');
if (!text.trim()) throw new Error('Empty answer from Gemini: ' + JSON.stringify(response).slice(0, 500));
const { data } = $('Build prompt').first().json;
const { gemini_model, language } = $('Config').first().json;
const locale = /portug/i.test(language) ? 'pt-BR' : 'en-US';

const esc = v => String(v ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const month = d => String(d ?? '').slice(0, 7);
const num = v => v == null ? '-' : Number(v).toLocaleString(locale);
const rate = v => v == null ? '-' : Number(v).toLocaleString(locale, { minimumFractionDigits: 1, maximumFractionDigits: 1 });
const cell = 'style="padding:4px 10px;border-bottom:1px solid #ddd;text-align:left"';
const table = (title, header, rows) => rows.length === 0 ? '' :
  `<h3>${esc(title)}</h3><table style="border-collapse:collapse;font-size:13px"><tr>` +
  header.map(h => `<th ${cell}>${esc(h)}</th>`).join('') + '</tr>' +
  rows.map(r => '<tr>' + r.map(v => `<td ${cell}>${esc(v)}</td>`).join('') + '</tr>').join('') + '</table>';

const html = `<div style="font-family:Arial,sans-serif;max-width:760px;color:#222">
<h2 style="color:#1F4E79">Public safety weekly briefing - ${esc(month(data.window_start))} to ${esc(month(data.window_end))}</h2>
${text}
${table('Highest CVLI rates by state', ['#', 'State', 'Region', 'Rate /100k', 'Victims'],
  data.highest_state_rates.map(s => [s.rank, s.state, s.region, rate(s.cvli_rate_100k), num(s.cvli_victims)]))}
${table('Hotspots among cities with 100,000+ inhabitants', ['#', 'Municipality', 'State', 'Population', 'Rate /100k', 'LISA cluster'],
  data.largest_city_hotspots.map(c => [c.rank, c.municipality, c.state, num(c.population), rate(c.cvli_rate_100k), c.lisa_cluster]))}
${table('Data changed in the last 7 days', ['Dataset', 'Keys'],
  data.data_changes_last_7_days.map(c => [c.dataset, c.keys]))}
<p style="font-size:12px;color:#666">Numbers: Gold layer of the Public-Safety-Intelligence-Lakehouse (SINESP, IBGE, SENATRAN, Atlas Brasil).
Text: ${esc(gemini_model)}, instructed to use only these numbers. Sent by n8n.</p></div>`;

return [{ json: { subject: `PSI weekly briefing - ${month(data.window_end)}`, html } }];

const run = $input.first().json;
const state = run.status?.state ?? run.state?.life_cycle_state ?? 'UNKNOWN';
const result = run.status?.termination_details?.code ?? run.state?.result_state ?? 'not finished';
const message = run.status?.termination_details?.message ?? run.state?.state_message ?? '';
const started = run.start_time ? new Date(run.start_time).toISOString() : 'unknown';
const stale = run.start_time && Date.now() - run.start_time >= 26 * 3600 * 1000;
const esc = v => String(v ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const html = `<div style="font-family:Arial,sans-serif">
<h2 style="color:#B00020">PSI pipeline needs attention</h2>
<p>${stale ? 'The latest run of the pipeline job is older than 26 hours: the weekly run did not happen.'
           : 'The pipeline job did not finish successfully, so the weekly briefing was not sent.'}</p>
<ul><li>Run: ${esc(run.run_id)} (started ${esc(started)})</li><li>State: ${esc(state)} - ${esc(result)}</li>
<li>Message: ${esc(message)}</li></ul>
${run.run_page_url ? `<p><a href="${esc(run.run_page_url)}">Open the run in Databricks</a></p>` : ''}</div>`;
return [{ json: { subject: `PSI pipeline alert - ${result}`, html } }];
